WITH inner_cte AS ( SELECT so.OFFER_DEPT_NAME, sos.TOTAL_UNITS FROM SUBJECT_OFFERED so JOIN SUBJECT_OFFERED_SUMMARY sos ON so.SUBJECT_ID_SORT = sos.SUBJECT_ID_SORT WHERE so.TERM_CODE LIKE '2012%' AND so.OFFER_DEPT_NAME = 'Harvard Cross-Enrollment Prog' AND sos.CLUSTER_TYPE_DESC = 'SWE: School-Wide Electives' ) , dept_avg AS ( SELECT OFFER_DEPT_NAME, AVG(TOTAL_UNITS) AS avg_units FROM inner_cte GROUP BY OFFER_DEPT_NAME ) , overall_avg AS ( SELECT AVG(TOTAL_UNITS) AS overall_avg_units FROM inner_cte ) SELECT d.OFFER_DEPT_NAME, d.avg_units, o.overall_avg_units, CASE WHEN d.avg_units > o.overall_avg_units * 1.1 THEN 'ABOVE_AVERAGE' WHEN d.avg_units < o.overall_avg_units * 0.9 THEN 'BELOW_AVERAGE' ELSE 'AVERAGE' END AS department_performance FROM dept_avg d CROSS JOIN overall_avg o;